// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Deploy a helper that always reverts on ETH receipt
        Reverter reverter = new Reverter();
        address adversary = address(reverter);

        // Deposit as the adversary to build credit
        vm.deal(adversary, amount);
        vm.prank(adversary);
        c.deposit{value: amount}();

        // Record contract balance before withdraw
        uint256 balanceBefore = address(c).balance;

        // Withdraw as the adversary (call will fail)
        vm.prank(adversary);
        c.withdrawAll();

        // After a successful withdrawAll, the contract's balance must drop by exactly `amount`.
        // The correct version reverts (so the assertion on balance is never reached for a failing call).
        // The buggy version silently ignores the failed transfer but still zeroes credit and reduces balance.
        assertTrue(address(c).balance == balanceBefore - amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

