pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict to sensible amounts, keep it wide
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Deploy an adversarial callee whose fallback always reverts
        Reverter reverter = new Reverter();
        Reverter reverter2 = new Reverter(); // different address

        // Fund and deposit from a normal EOA (uses reverter as unrelated account)
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();

        // Record state before the adversarial withdraw
        uint256 creditBefore = c.credit(address(reverter));
        uint256 balanceBefore = address(c).balance;

        // The adversarial counterparty (reverter) attempts to withdrawAll
        vm.deal(address(reverter), 0);
        vm.prank(address(reverter));
        try c.withdrawAll() { } catch { }

        // After a failed transfer, credit must remain unchanged and balance unchanged
        assertTrue(c.credit(address(reverter)) == creditBefore && address(c).balance == balanceBefore);
    }
}

