pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < 1e36);
        vm.assume(actor != address(0) && actor.code.length == 0);

        Reverter reverter = new Reverter();
        address caller = actor;
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        uint256 callerCreditAfter = c.credit(caller);
        bool transferFailed = amount > 0 && address(reverter).balance == 0;
        assertTrue(
            (callerCreditAfter == 0) &&
            (transferFailed ? balanceAfter == balanceBefore : balanceAfter == balanceBefore - amount)
        );
    }
}

