pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 amount, uint8 mode) public {
        vm.assume(amount > 0);
        address caller = address(new RevertingReceiver());
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        if (mode % 2 == 0) {
            vm.prank(caller);
            c.withdrawAll();
        } else {
            // Call via another acccount that has 0 credit; still exercises the property on every account's balance.
            address other = address(0x1234);
            vm.prank(other);
            c.withdrawAll();
        }

        uint256 ethBal = address(c).balance;
        uint256 internalBal = c.balance();
        assertEq(ethBal, internalBal, "ETH balance equals internal balance");
    }
}

contract RevertingReceiver {
    fallback() external payable {
        revert();
    }
}

