pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 depositAmt, uint128 withdrawAmt, address depositor, address withdrawer) public {
        vm.assume(depositor != withdrawer);
        vm.assume(depositor != address(0) && withdrawer != address(0));
        vm.assume(depositor != address(c) && withdrawer != address(c));
        vm.assume(depositAmt > 0 && withdrawAmt > 0);
        vm.assume(depositAmt >= withdrawAmt);

        // depositor deposits
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        c.deposit{value: depositAmt}();

        // withdrawer deposits a separate amount, so they have credit
        vm.deal(withdrawer, withdrawAmt);
        vm.prank(withdrawer);
        c.deposit{value: withdrawAmt}();

        // record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;

        // withdrawer withdraws all
        vm.prank(withdrawer);
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        // after correct withdrawal, contract balance should be depositAmt (depositor's credit)
        // and depositor credit is still depositAmt.
        // Bug: withdrawer's credit is set to 1 instead of 0, so sum of credits > depositAmt,
        // but balanceAfter = depositAmt.
        // So balanceAfter < (depositor credit + withdrawer credit).
        // Reference: balanceAfter == depositAmt (since depositor credit is depositAmt, withdrawer is 0)
        // Bug: balanceAfter == depositAmt, but sum of credits = depositAmt + 1.
        uint256 depositorCredit = c.credit(depositor);
        uint256 withdrawerCredit = c.credit(withdrawer);
        assertTrue(balanceAfter == depositorCredit + withdrawerCredit);
    }
}

