pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address caller) public {
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        // Make deposits from fuzzed caller to establish credit
        vm.deal(caller, amount1 + amount2);
        vm.prank(caller);
        c.deposit{value: amount1}();
        vm.prank(caller);
        c.deposit{value: amount2}();

        // Withdraw all credit
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        vm.assume(success);

        // After successful withdrawal, contract balance must equal sum of all credits.
        // The bug leaves credit[caller] = 1 while having subtracted full credit from balance,
        // so balance becomes less than total credit sum.
        uint256 totalCredits = c.credit(address(this)) + c.credit(caller) + c.credit(address(0));
        assertEq(address(c).balance, totalCredits);
    }
}

