pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawActorSeed, uint8 actorCount) public {
        // Restrict deposit amount to avoid overflow and keep domain wide
        vm.assume(depositAmount < type(uint128).max);
        vm.assume(actorCount >= 1 && actorCount <= 10);

        // Generate pseudo-random addresses from the seed
        address[] memory actors = new address[](actorCount);
        for (uint8 i = 0; i < actorCount; i++) {
            actors[i] = address(uint160(uint256(keccak256(abi.encode(withdrawActorSeed, i)))));
            vm.assume(actors[i] != address(0) && actors[i] != address(c));
        }

        // Deposit from multiple actors to build up state
        for (uint8 i = 0; i < actorCount; i++) {
            vm.deal(actors[i], depositAmount);
            vm.prank(actors[i]);
            c.deposit{value: depositAmount}();
        }

        // Choose one actor to withdraw
        address withdrawer = actors[uint256(keccak256(abi.encode(withdrawActorSeed))) % actorCount];

        // Perform withdrawal
        vm.prank(withdrawer);
        c.withdrawAll();

        // Assert: contract balance >= sum of all user credits (holds for reference, violated by mutant)
        uint256 totalCredit;
        for (uint8 i = 0; i < actorCount; i++) {
            // Credits are public mapping with auto-generated getter
            totalCredit += c.credit(actors[i]);
        }
        uint256 contractBalance = c.balance();
        assertTrue(contractBalance >= totalCredit);
    }
}

