pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 seed) public {
        // Bound amounts to reasonable positive values
        depositAmount = bound(depositAmount, 1, 100 ether);
        // withdrawAmount must not exceed depositAmount for the single-actor case to be valid
        vm.assume(withdrawAmount <= depositAmount);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        // Use a deterministic set of actors from the seed
        address actor1 = address(uint160(uint256(keccak256(abi.encode(seed, 0)))));
        address actor2 = address(uint160(uint256(keccak256(abi.encode(seed, 1)))));
        address actor3 = address(uint160(uint256(keccak256(abi.encode(seed, 2)))));

        // Actor1 deposits depositAmount
        vm.deal(actor1, depositAmount);
        vm.prank(actor1);
        c.deposit{value: depositAmount}();

        // Actor2 deposits a random fraction
        uint256 actor2Dep = bound(uint256(keccak256(abi.encode(seed, 3))), 0, depositAmount / 2);
        vm.deal(actor2, actor2Dep);
        vm.prank(actor2);
        c.deposit{value: actor2Dep}();

        // Actor3 deposits a small random fraction
        uint256 actor3Dep = bound(uint256(keccak256(abi.encode(seed, 4))), 0, depositAmount / 3);
        vm.deal(actor3, actor3Dep);
        vm.prank(actor3);
        c.deposit{value: actor3Dep}();

        // Record total credit before withdrawal
        // Credits are private, we cannot read them. We will compute expected total credit externally as sum of deposits minus withdrawn amounts.
        // We track deposits and withdrawals per actor off-chain.
        uint256 totalDeposited = depositAmount + actor2Dep + actor3Dep;
        uint256 totalWithdrawnBefore = 0;

        // Actor1 withdraws a fraction
        if (withdrawAmount > 0) {
            vm.prank(actor1);
            c.withdrawAll();
            totalWithdrawnBefore += depositAmount; // withdrawAll drains all credit for actor1
        }

        // Now we need to compute total remaining credit from the remaining actors.
        // Actor2 and Actor3 may have credits.
        // But we cannot read internal credit mapping. So we cannot directly assert on total credit.
        // Instead, we assert that the contract's tracked balance variable (public) equals the actual ETH balance.
        // Since the bug leaves the tracked balance unchanged, it will be higher than actual ETH balance after withdrawal.
        assertEq(c.balance(), address(c).balance);
    }
}

