pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        vm.assume(user != address(0) && user != address(c) && user != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint120).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Ensure user has sufficient ETH to deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Record pre-withdraw balance state
        uint256 expectedCreditBefore = c.credit(user);
        uint256 expectedBalanceBefore = c.balance();
        uint256 expectedContractBalanceBefore = address(c).balance;

        // Withdraw: user initiates withdrawAll, gets back value via fallback
        // To prevent revert from a simple EOA (which always succeeds), we deploy a helper that accepts ETH
        WithdrawHelper helper = new WithdrawHelper();
        // Move credit to helper's address so it can withdraw
        // Actually we need the original depositor to call withdrawAll, but the call sends funds to msg.sender.
        // An EOA msg.sender always succeeds on low-level call, so no adversarial helper is strictly needed for reentrancy/failure.
        // However, we must ensure msg.sender is an EOA so call succeeds. The fuzzed `user` is an EOA => call always succeeds.
        // So we can call withdrawAll directly.
        vm.prank(user);
        c.withdrawAll();

        // Invariant: balance variable == total deposited - total withdrawn
        // After one deposit and one full withdrawal, credit[user] == 0, balance should be 0.
        // The reference contract satisfies this; the mutant will have balance == depositAmount * 2.
        assertTrue(c.balance() == 0);
    }
}

contract WithdrawHelper {
    fallback() external payable {}
}

