// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to admissible domain: depositAmount > 0, withdrawAmount <= depositAmount
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        // Setup depositor with funds
        address depositor = address(0x1234);
        vm.deal(depositor, depositAmount);

        // Deposit
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Track expected balance after potential DDoS withdrawal
        // We will use a helper that simply accepts Ether to ensure call succeeds
        Reverter helper = new Reverter(); // Not actually a reverter, just an EOA-like contract that accepts Ether
        vm.deal(address(helper), 0);

        // The buggy version modifies balance incorrectly on withdrawal. We need to trigger withdrawAll.
        // But the user calling withdrawAll must have some credit. We'll use depositor.
        // However, the adversarial counterparty rule requires a helper if the difference relies on external call behavior.
        // Here the difference is purely arithmetic: balance increases instead of decreasing.
